mapper.sql:
FROM t_rule_set rs
JOIN t_rule_set_version rsv ON rsv.rule_set_version_id = rs.current_rule_set_version_id
JOIN t_decision_point dp ON dp.decision_point_id = rs.decision_point_id
WHERE rs.status = 'CONFIGURABLE'

    AND dp.point_code = #{pointCode}


    AND rsv.rule_set_code = #{ruleSetCode}


    AND rsv.status = #{status}

mapper.select:
SELECT decision_point_id, point_code, point_name, business_domain, status, create_time, update_time
FROM t_decision_point
WHERE point_code = #{pointCode}

SELECT decision_point_id, point_code, point_name, business_domain, status, create_time, update_time
FROM t_decision_point
WHERE decision_point_id = #{decisionPointId}

SELECT decision_point_id, point_code, point_name, business_domain, status, create_time, update_time FROM t_decision_point WHERE decision_point_id IN
#{decisionPointId}
ORDER BY decision_point_id

SELECT binding_id, point_version_id, rule_set_version_id, sequence_no, create_time FROM t_decision_point_rule_set WHERE rule_set_version_id IN
#{ruleSetVersionId}
ORDER BY rule_set_version_id, point_version_id, sequence_no, binding_id

SELECT binding_id, point_version_id, rule_set_version_id, sequence_no, create_time FROM t_decision_point_rule_set WHERE point_version_id IN
#{pointVersionId}
ORDER BY point_version_id, sequence_no, binding_id

SELECT node_id, rule_id, parent_node_id, node_type, group_operator, comparison_operator, sequence_no, create_time, update_time FROM t_rule_node WHERE rule_id IN
#{ruleId}
ORDER BY rule_id, sequence_no, node_id

SELECT variable_code, numeric_unit, currency_code, currency_variable_code, operand_id, node_id, operand_role, value_sequence, source_type, feature_version_id, field_code, value_type, string_value, number_value, boolean_value, datetime_value, duration_value, create_time, update_time FROM t_rule_operand WHERE node_id IN
#{nodeId}
ORDER BY node_id, CASE operand_role WHEN 'LEFT' THEN 0 ELSE 1 END, value_sequence, operand_id

SELECT target_binding_code, rule_action_id, rule_id, action_version_id, sequence_no, create_time FROM t_rule_action WHERE rule_id IN
#{ruleId}
ORDER BY rule_id, sequence_no, rule_action_id

SELECT action_version_id, action_code, action_name, action_category, version_no, handler_code, implementation_version, implementation_hash, terminal_flag, decision_code, merge_policy, shadow_supported_flag, status, create_time, update_time FROM t_action_version WHERE action_version_id IN
#{actionVersionId}
ORDER BY action_version_id

SELECT parameter_definition_id, action_version_id, parameter_code, value_type, required_flag, allowed_source_type, target_parameter_flag, create_time FROM t_action_parameter_definition WHERE action_version_id IN
#{actionVersionId}
ORDER BY action_version_id, parameter_code, parameter_definition_id

SELECT variable_code, parameter_id, rule_action_id, parameter_definition_id, value_sequence, source_type, feature_version_id, field_code, string_value, number_value, boolean_value, datetime_value, duration_value, create_time FROM t_rule_action_parameter WHERE rule_action_id IN
#{ruleActionId}
ORDER BY rule_action_id, parameter_definition_id, value_sequence, parameter_id

SELECT feature_version_id, feature_code, feature_name, business_category, version_no, result_value_type, handler_code, implementation_version, implementation_hash, timeout_ms, status, create_time, update_time FROM t_feature_version WHERE feature_version_id IN
#{featureVersionId}
ORDER BY feature_version_id

SELECT dependency_id, feature_version_id, dependency_feature_version_id, sequence_no, required_flag, create_time FROM t_feature_dependency WHERE feature_version_id IN
#{featureVersionId}
ORDER BY feature_version_id, sequence_no, dependency_id

mapper.update:
UPDATE t_rule_set_version
SET status = 'RETIRED',
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE rule_set_version_id = #{ruleSetVersionId}
  AND status = #{expectedStatus}

UPDATE t_decision_point_version
SET status = 'RETIRED',
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE point_version_id = #{pointVersionId}
  AND status = #{expectedStatus}

UPDATE t_rule_set_version
SET status = 'FROZEN',
    frozen_by = #{frozenBy},
    frozen_time = #{frozenTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler},
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE rule_set_version_id = #{ruleSetVersionId}
  AND status = #{expectedStatus}
  AND content_hash = #{expectedContentHash}

UPDATE t_decision_point_version
SET status = 'FROZEN',
    update_time = #{updateTime,jdbcType=TIMESTAMP,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE point_version_id = #{pointVersionId}
  AND status = #{expectedStatus}
  AND content_hash = #{expectedContentHash}

UPDATE t_rule_set SET current_rule_set_version_id = #{currentVersionId}, version = version + 1,
    update_time = #{time,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE rule_set_id = #{value.ruleSetId} AND version = #{value.version}
    AND current_rule_set_version_id = #{value.currentRuleSetVersionId} AND status = 'CONFIGURABLE'

UPDATE t_rule_set SET status = 'DELETED', version = version + 1, deleted_by = #{actorId},
    deleted_time = #{time,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}, delete_reason_code = 'OPERATOR_REQUEST', delete_trigger_id = #{triggerId},
    update_time = #{time,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE rule_set_id = #{value.ruleSetId} AND version = #{value.version}
    AND current_rule_set_version_id = #{value.currentRuleSetVersionId} AND status = 'CONFIGURABLE'
